import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { aggregate } from "../server/dist/service.js";
import { enrichFilms } from "../server/dist/letterboxd.js";
import { addDays, todayInRome } from "../server/dist/dates.js";

/**
 * Pre-fetch the full programming into a static JSON file. It is used as a
 * fallback by the browser engine when every public CORS proxy is unavailable,
 * and is regenerated by the deploy workflow on a schedule.
 *
 * Letterboxd ratings/links are resolved here too and cached in
 * `server/data/letterboxd-cache.json` (committed to the repo).
 *
 * Requires the server to be built first (`npm -w server run build`).
 */
const here = path.dirname(fileURLToPath(import.meta.url));
const days = Number(process.env.SNAPSHOT_DAYS ?? 90);

const from = todayInRome();
const to = addDays(from, days);

const { showtimes, failures } = await aggregate(from, to);

const uniqueFilms = new Map();
for (const st of showtimes) {
  if (!uniqueFilms.has(st.filmKey)) {
    uniqueFilms.set(st.filmKey, {
      filmKey: st.filmKey,
      title: st.title,
      originalTitle: st.originalTitle,
    });
  }
}

console.log(`[snapshot] resolving ${uniqueFilms.size} films on Letterboxd…`);
const films = await enrichFilms([...uniqueFilms.values()]);
console.log(`[snapshot] letterboxd: ${Object.keys(films).length}/${uniqueFilms.size} matched`);

const payload = {
  generatedAt: new Date().toISOString(),
  from,
  to,
  showtimes,
  failures,
  films,
};

const dir = path.resolve(here, "../web/public/data");
await mkdir(dir, { recursive: true });
const file = path.join(dir, "snapshot.json");
await writeFile(file, JSON.stringify(payload));

const kb = (Buffer.byteLength(JSON.stringify(payload)) / 1024).toFixed(0);
console.log(
  `[snapshot] ${showtimes.length} showtimes (${from} → ${to}, ${kb} kB) → ${path.relative(process.cwd(), file)}`,
);
if (failures.length) console.warn(`[snapshot] ${failures.length} cinema failure(s):`, failures);
